void MonitorPanel::on_select_printer(wxCommandEvent& event)
{
    Slic3r::DeviceManager* dev = Slic3r::GUI::wxGetApp().getDeviceManager();
    const std::string requested_dev_id = event.GetString().ToStdString();
    BOOST_LOG_TRIVIAL(trace) << "Orca diagnostic: MonitorPanel::on_select_printer requested_dev_id="
                            << requested_dev_id << " device_manager=" << (dev ? "set" : "null");
    if (!dev) return;

    if ( dev->get_selected_machine() && (dev->get_selected_machine()->get_dev_id() != event.GetString().ToStdString()) && m_hms_panel) {
        m_hms_panel->clear_hms_tag();
    }

    const bool selected = dev->set_selected_machine(requested_dev_id);
    BOOST_LOG_TRIVIAL(trace) << "Orca diagnostic: MonitorPanel::on_select_printer set_selected_machine result="
                            << selected << " selected_dev_id="
                            << (dev->get_selected_machine() ? dev->get_selected_machine()->get_dev_id() : "<null>");
    if (!selected)
        return;

    set_default();
    update_all();

    Tab*          tab     = wxGetApp().get_tab(Preset::TYPE_PRINT);
    if (presets == nullptr || tab == nullptr || presets->prints.find_preset(preset_name) == nullptr)
        return false;
    tab->select_preset(preset_name);
    plater.on_config_change(presets->full_config());
    return true;
}

bool select_named_printer(Plater& plater, const std::string& name)
{
    const auto saved = Printers::named_printers();
    const auto found = std::find_if(saved.begin(), saved.end(), [&](const auto& printer) { return printer.name == name; });
    if (found == saved.end() || !select_printer_preset(plater, name) || current_printer().preset_name != name)
        return false;

    if (DeviceManager* devices = wxGetApp().getDeviceManager()) {
        MachineObject* selected = devices->get_selected_machine();
        const std::string selected_id = selected == nullptr ? std::string() : selected->get_dev_id();
        if (found->device_id.empty() || selected_id != found->device_id)
            devices->set_selected_machine(found->device_id);
    }
    return true;
}

